-- 审批工作流最终增量校验：管理端是否还有切流后的残留写入
--
-- 判定：admin_count > workflow_count 表示旧库可能仍有切流后的新行（RESIDUAL）。
-- 若有残留，先停止管理端写入，再执行 workflow_final_copy.sql 按 id 补齐。
--
-- 执行：
--   docker exec -i iboot-mysql mysql -uroot -proot < scripts/migrate/workflow_final_check.sql

SELECT table_name, admin_count, workflow_count,
       CASE WHEN admin_count > workflow_count THEN 'RESIDUAL' ELSE 'OK' END AS verdict
FROM (
  SELECT 'ACT_EVT_LOG' AS table_name, (SELECT COUNT(*) FROM iboot_admin.ACT_EVT_LOG) AS admin_count, (SELECT COUNT(*) FROM iboot_workflow.ACT_EVT_LOG) AS workflow_count
  UNION ALL SELECT 'ACT_GE_BYTEARRAY', (SELECT COUNT(*) FROM iboot_admin.ACT_GE_BYTEARRAY), (SELECT COUNT(*) FROM iboot_workflow.ACT_GE_BYTEARRAY)
  UNION ALL SELECT 'ACT_GE_PROPERTY', (SELECT COUNT(*) FROM iboot_admin.ACT_GE_PROPERTY), (SELECT COUNT(*) FROM iboot_workflow.ACT_GE_PROPERTY)
  UNION ALL SELECT 'ACT_HI_ACTINST', (SELECT COUNT(*) FROM iboot_admin.ACT_HI_ACTINST), (SELECT COUNT(*) FROM iboot_workflow.ACT_HI_ACTINST)
  UNION ALL SELECT 'ACT_HI_ATTACHMENT', (SELECT COUNT(*) FROM iboot_admin.ACT_HI_ATTACHMENT), (SELECT COUNT(*) FROM iboot_workflow.ACT_HI_ATTACHMENT)
  UNION ALL SELECT 'ACT_HI_COMMENT', (SELECT COUNT(*) FROM iboot_admin.ACT_HI_COMMENT), (SELECT COUNT(*) FROM iboot_workflow.ACT_HI_COMMENT)
  UNION ALL SELECT 'ACT_HI_DETAIL', (SELECT COUNT(*) FROM iboot_admin.ACT_HI_DETAIL), (SELECT COUNT(*) FROM iboot_workflow.ACT_HI_DETAIL)
  UNION ALL SELECT 'ACT_HI_ENTITYLINK', (SELECT COUNT(*) FROM iboot_admin.ACT_HI_ENTITYLINK), (SELECT COUNT(*) FROM iboot_workflow.ACT_HI_ENTITYLINK)
  UNION ALL SELECT 'ACT_HI_IDENTITYLINK', (SELECT COUNT(*) FROM iboot_admin.ACT_HI_IDENTITYLINK), (SELECT COUNT(*) FROM iboot_workflow.ACT_HI_IDENTITYLINK)
  UNION ALL SELECT 'ACT_HI_PROCINST', (SELECT COUNT(*) FROM iboot_admin.ACT_HI_PROCINST), (SELECT COUNT(*) FROM iboot_workflow.ACT_HI_PROCINST)
  UNION ALL SELECT 'ACT_HI_TASKINST', (SELECT COUNT(*) FROM iboot_admin.ACT_HI_TASKINST), (SELECT COUNT(*) FROM iboot_workflow.ACT_HI_TASKINST)
  UNION ALL SELECT 'ACT_HI_TSK_LOG', (SELECT COUNT(*) FROM iboot_admin.ACT_HI_TSK_LOG), (SELECT COUNT(*) FROM iboot_workflow.ACT_HI_TSK_LOG)
  UNION ALL SELECT 'ACT_HI_VARINST', (SELECT COUNT(*) FROM iboot_admin.ACT_HI_VARINST), (SELECT COUNT(*) FROM iboot_workflow.ACT_HI_VARINST)
  UNION ALL SELECT 'ACT_PROCDEF_INFO', (SELECT COUNT(*) FROM iboot_admin.ACT_PROCDEF_INFO), (SELECT COUNT(*) FROM iboot_workflow.ACT_PROCDEF_INFO)
  UNION ALL SELECT 'ACT_RE_DEPLOYMENT', (SELECT COUNT(*) FROM iboot_admin.ACT_RE_DEPLOYMENT), (SELECT COUNT(*) FROM iboot_workflow.ACT_RE_DEPLOYMENT)
  UNION ALL SELECT 'ACT_RE_MODEL', (SELECT COUNT(*) FROM iboot_admin.ACT_RE_MODEL), (SELECT COUNT(*) FROM iboot_workflow.ACT_RE_MODEL)
  UNION ALL SELECT 'ACT_RE_PROCDEF', (SELECT COUNT(*) FROM iboot_admin.ACT_RE_PROCDEF), (SELECT COUNT(*) FROM iboot_workflow.ACT_RE_PROCDEF)
  UNION ALL SELECT 'ACT_RU_ACTINST', (SELECT COUNT(*) FROM iboot_admin.ACT_RU_ACTINST), (SELECT COUNT(*) FROM iboot_workflow.ACT_RU_ACTINST)
  UNION ALL SELECT 'ACT_RU_DEADLETTER_JOB', (SELECT COUNT(*) FROM iboot_admin.ACT_RU_DEADLETTER_JOB), (SELECT COUNT(*) FROM iboot_workflow.ACT_RU_DEADLETTER_JOB)
  UNION ALL SELECT 'ACT_RU_ENTITYLINK', (SELECT COUNT(*) FROM iboot_admin.ACT_RU_ENTITYLINK), (SELECT COUNT(*) FROM iboot_workflow.ACT_RU_ENTITYLINK)
  UNION ALL SELECT 'ACT_RU_EVENT_SUBSCR', (SELECT COUNT(*) FROM iboot_admin.ACT_RU_EVENT_SUBSCR), (SELECT COUNT(*) FROM iboot_workflow.ACT_RU_EVENT_SUBSCR)
  UNION ALL SELECT 'ACT_RU_EXECUTION', (SELECT COUNT(*) FROM iboot_admin.ACT_RU_EXECUTION), (SELECT COUNT(*) FROM iboot_workflow.ACT_RU_EXECUTION)
  UNION ALL SELECT 'ACT_RU_EXTERNAL_JOB', (SELECT COUNT(*) FROM iboot_admin.ACT_RU_EXTERNAL_JOB), (SELECT COUNT(*) FROM iboot_workflow.ACT_RU_EXTERNAL_JOB)
  UNION ALL SELECT 'ACT_RU_HISTORY_JOB', (SELECT COUNT(*) FROM iboot_admin.ACT_RU_HISTORY_JOB), (SELECT COUNT(*) FROM iboot_workflow.ACT_RU_HISTORY_JOB)
  UNION ALL SELECT 'ACT_RU_IDENTITYLINK', (SELECT COUNT(*) FROM iboot_admin.ACT_RU_IDENTITYLINK), (SELECT COUNT(*) FROM iboot_workflow.ACT_RU_IDENTITYLINK)
  UNION ALL SELECT 'ACT_RU_JOB', (SELECT COUNT(*) FROM iboot_admin.ACT_RU_JOB), (SELECT COUNT(*) FROM iboot_workflow.ACT_RU_JOB)
  UNION ALL SELECT 'ACT_RU_SUSPENDED_JOB', (SELECT COUNT(*) FROM iboot_admin.ACT_RU_SUSPENDED_JOB), (SELECT COUNT(*) FROM iboot_workflow.ACT_RU_SUSPENDED_JOB)
  UNION ALL SELECT 'ACT_RU_TASK', (SELECT COUNT(*) FROM iboot_admin.ACT_RU_TASK), (SELECT COUNT(*) FROM iboot_workflow.ACT_RU_TASK)
  UNION ALL SELECT 'ACT_RU_TIMER_JOB', (SELECT COUNT(*) FROM iboot_admin.ACT_RU_TIMER_JOB), (SELECT COUNT(*) FROM iboot_workflow.ACT_RU_TIMER_JOB)
  UNION ALL SELECT 'ACT_RU_VARIABLE', (SELECT COUNT(*) FROM iboot_admin.ACT_RU_VARIABLE), (SELECT COUNT(*) FROM iboot_workflow.ACT_RU_VARIABLE)
  UNION ALL SELECT 'biz_leave_application', (SELECT COUNT(*) FROM iboot_admin.biz_leave_application), (SELECT COUNT(*) FROM iboot_workflow.biz_leave_application)
  UNION ALL SELECT 'FLW_RU_BATCH', (SELECT COUNT(*) FROM iboot_admin.FLW_RU_BATCH), (SELECT COUNT(*) FROM iboot_workflow.FLW_RU_BATCH)
  UNION ALL SELECT 'FLW_RU_BATCH_PART', (SELECT COUNT(*) FROM iboot_admin.FLW_RU_BATCH_PART), (SELECT COUNT(*) FROM iboot_workflow.FLW_RU_BATCH_PART)
) t;

SELECT (SELECT COALESCE(MAX(id), 0) FROM iboot_admin.biz_leave_application) AS admin_max_id,
       (SELECT COALESCE(MAX(id), 0) FROM iboot_workflow.biz_leave_application) AS workflow_max_id;

-- 业务表按 id 的残留检查：计数差可能被新库更多的数据掩盖，必须直接比较 id 水位
SELECT COUNT(*) AS admin_rows_newer_than_workflow_max
FROM iboot_admin.biz_leave_application
WHERE id > (SELECT COALESCE(MAX(id), 0) FROM iboot_workflow.biz_leave_application);
